// Single place to configure this workflow. Nothing here is a secret: the Supabase key
// lives in the credential and the bot token lives in the Telegram credential.
const SUPABASE_URL = '';   // TODO: https://<project>.supabase.co
const CHAT_ID = '';        // TODO: id of the chat that receives the digest

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Config"');
if (!CHAT_ID) throw new Error('CHAT_ID is not configured in "Config"');

const base = SUPABASE_URL.replace(/\/+$/, '');
return [{
  json: {
    chatId: CHAT_ID,
    sourcesUrl: base + '/rest/v1/sources?select=url,title,category&enabled=eq.true',
  },
}];

// Turns whatever the feeds returned into one dedup request for workflow 02.
// Capping happens HERE, before deduplication, on purpose: workflow 02 records every
// item it is given as seen, so anything capped after it would be silently lost
// forever. Capping first means the overflow is simply picked up tomorrow.
const MAX_PER_RUN = 15;

const entries = $input.all().map((i) => i.json || {});

const normalised = entries.map((e) => {
  const url = String(e.link || e.url || e.guid || '').trim();
  const title = String(e.title || '').trim();
  const published = e.isoDate || e.pubDate || e.published || null;
  const excerpt = String(e.contentSnippet || e.summary || e.content || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 400);
  return { url, title, published_at: published ? new Date(published).toISOString() : null, excerpt };
}).filter((e) => e.url && e.title);

// Newest first, so a capped run keeps the freshest items rather than an arbitrary slice.
normalised.sort((a, b) => {
  const ta = a.published_at ? Date.parse(a.published_at) : 0;
  const tb = b.published_at ? Date.parse(b.published_at) : 0;
  return tb - ta;
});

const capped = normalised.slice(0, MAX_PER_RUN);

return [{
  json: {
    source: 'digest',
    key_field: 'url',
    items: capped,
    fetched: normalised.length,
    carriedOver: Math.max(0, normalised.length - capped.length),
  },
}];

// Builds one LLM request for the whole batch. One call, not one per item: cheaper,
// and it lets the model tag consistently across the digest.
const dedup = $input.first().json || {};
const items = Array.isArray(dedup.new_items) ? dedup.new_items : [];

const list = items.map((it, n) => [
  '[' + (n + 1) + '] ' + it.title,
  'url: ' + it.url,
  it.excerpt ? 'excerpt: ' + it.excerpt : null,
].filter(Boolean).join('\n')).join('\n\n');

return [{
  json: {
    count: items.length,
    items,
    system: 'You summarise a feed digest for one busy reader. One line per entry, no retelling.',
    user: 'Summarise each entry below. Keep one_liner under 120 characters and say what it is,'
      + ' not that it exists. why_it_matters is one short clause or an empty string when there is'
      + ' nothing to say. tag is a lowercase single word grouping similar entries.\n\n' + list,
    max_retries: 2,
    schema: {
      type: 'object',
      required: ['items'],
      properties: {
        items: {
          type: 'array',
          items: {
            type: 'object',
            required: ['url', 'one_liner', 'tag'],
            properties: {
              url: { type: 'string' },
              one_liner: { type: 'string' },
              why_it_matters: { type: 'string' },
              tag: { type: 'string' },
            },
          },
        },
      },
    },
  },
}];

// Builds the Telegram message. Grouped by tag, one line per entry, link on the title.
const llm = $input.first().json || {};
const batch = $('Build digest request').first().json;

const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// If the model failed after its retries, fall back to titles rather than skipping the
// digest: the reader still gets the links, just without the summaries.
const summarised = llm.ok && llm.data && Array.isArray(llm.data.items) ? llm.data.items : [];
const byUrl = new Map(summarised.map((s) => [s.url, s]));

const rows = batch.items.map((item) => {
  const s = byUrl.get(item.url) || {};
  return {
    tag: String(s.tag || 'other').toLowerCase(),
    title: item.title,
    url: item.url,
    one_liner: s.one_liner || '',
    why: s.why_it_matters || '',
  };
});

const groups = new Map();
for (const row of rows) {
  if (!groups.has(row.tag)) groups.set(row.tag, []);
  groups.get(row.tag).push(row);
}

const parts = ['<b>Morning digest</b>', ''];
for (const [tag, list] of [...groups.entries()].sort((a, b) => a[0].localeCompare(b[0]))) {
  parts.push('<b>' + esc(tag) + '</b>');
  for (const row of list) {
    const line = '• <a href="' + row.url + '">' + esc(row.title) + '</a>';
    parts.push(row.one_liner ? line + '\n  ' + esc(row.one_liner) : line);
    if (row.why) parts.push('  <i>' + esc(row.why) + '</i>');
  }
  parts.push('');
}

const footer = [];
if (batch.carriedOver > 0) footer.push(batch.carriedOver + ' more waiting for tomorrow');
if (!llm.ok) footer.push('summaries unavailable, titles only');
if (footer.length) parts.push('<i>' + esc(footer.join(' · ')) + '</i>');

return [{
  json: {
    text: parts.join('\n').trim(),
    count: rows.length,
    degraded: !llm.ok,
  },
}];
